    "originType": "AUTORAL_PROFESSOR",
    "statement": "Em célebre debate com Axel Honneth, a filósofa Nancy Fraser critica a redução de toda injustiça social a questões identitárias ou psicossociais de reconhecimento, sustentando que muitas injustiças estruturais exigem simultaneamente reforma econômica e mudança institucional política.",
    "options": [
      {
        "letter": "A",
        "text": "Nancy Fraser propõe o conceito de PARIDADE DE PARTICIPAÇÃO (norma de justiça segundo a qual arranjos sociais devem permitir a todos os membros interagir como pares) estruturado em TRÊS DIMENSÕES irredutíveis (\"justiça tridimensional\"): (1) REDISTRIBUIÇÃO (dimensão econômica — combate à má distribuição, exploração e pobreza); (2) RECONHECIMENTO (dimensão cultural-simbólica — combate ao desrespeito e hierarquias de status, tratado por Fraser não como psicologia individual, mas como STATUS SOCIAL institucionalizado!); e (3) REPRESENTAÇÃO (dimensão política — combate à exclusão de voz e \"mau enquadramento\" nas fronteiras da comunidade política global). Ademais, distingue remédios AFIRMATIVOS (corrigem efeitos superficiais sem tocar nas estruturas geradoras) de remédios TRANSFORMATIVOS (reestruturam as causas profundas econômicas e culturais)!"
      },
      {
        "letter": "B",
        "text": "Para Nancy Fraser, toda injustiça econômica de classe e pobreza desaparece automaticamente caso haja apenas reconhecimento cultural simbólico, dispensando políticas de redistribuição material."
      },
      {
        "letter": "C",
        "text": "Nancy Fraser concorda integralmente com Axel Honneth ao fundamentar o reconhecimento na psicologia individual da autoestima ferida."
      },
      {
        "letter": "D",
        "text": "Na classificação de Nancy Fraser, os remédios \"afirmativos\" alteram radicalmente as estruturas econômicas e culturais profundas geradoras de desigualdade."
      }
    ],
    "correctAnswer": "A",
    "justification": "Nancy Fraser fundamenta a justiça na Paridade de Participação em três dimensões autônomas e articuladas: Redistribuição (econômica), Reconhecimento (status social cultural institucionalizado, não mera psicologia) e Representação (política, inclusive transnacional), distinguindo soluções afirmativas (superficiais) de transformativas (estruturais).",
